package com.hms.api;
import com.hms.repo.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.core.Authentication;import org.springframework.http.*;import java.util.*;
@RestController @RequestMapping("/api/reports") public class ReportController {
 private final PatientRepository patients;private final AppointmentRepository appointments;private final BillRepository bills;private final LaboratoryTestRepository labs;private final PharmacyItemRepository pharmacy;private final EmployeeRepository employees;private final AuditLogRepository audit;
 public ReportController(PatientRepository p,AppointmentRepository a,BillRepository b,LaboratoryTestRepository l,PharmacyItemRepository ph,EmployeeRepository e,AuditLogRepository au){patients=p;appointments=a;bills=b;labs=l;pharmacy=ph;employees=e;audit=au;}
 @GetMapping public Map<String,Object> dashboard(Authentication a){Map<String,Object> result=new LinkedHashMap<>();Set<String> roles=new HashSet<>();a.getAuthorities().forEach(x->roles.add(x.getAuthority()));boolean admin=roles.contains("ROLE_ADMIN");if(admin||roles.contains("ROLE_RECEPTIONIST")||roles.contains("ROLE_DOCTOR")||roles.contains("ROLE_NURSE"))result.put("patients",patients.count());if(admin||roles.contains("ROLE_RECEPTIONIST")||roles.contains("ROLE_DOCTOR"))result.put("appointments",appointments.count());if(admin||roles.contains("ROLE_ACCOUNTANT")||roles.contains("ROLE_RECEPTIONIST"))result.put("bills",bills.count());if(admin||roles.contains("ROLE_DOCTOR")||roles.contains("ROLE_LAB"))result.put("laboratoryTests",labs.count());if(admin||roles.contains("ROLE_PHARMACIST"))result.put("pharmacyItems",pharmacy.count());if(admin)result.put("employees",employees.count());return result;}
 @GetMapping("/audit") public Object audit(Authentication a){if(a.getAuthorities().stream().noneMatch(x->x.getAuthority().equals("ROLE_ADMIN")))return ResponseEntity.status(403).build();return audit.findAll();}
}
